1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	/**
22	 * One type covers both ops, so items/policy/incident are all optional. A
23	 * discriminated union on `op` would express this better, but the spec's
24	 * scenarios are plain object literals whose `op` widens to `string` and so
25	 * would no longer typecheck against literal `"quote"` / `"claim"` variants.
26	 * Revisit if a scenario parser ever narrows `op` on the way in.
27	 */
28	export type Step = {
29	  op: string;
30	  items?: Item[];
31	  policy?: number;
32	  incident?: Incident;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	export type ScenarioResult = {
44	  results: (QuoteResult | ClaimResult)[];
45	};
46	
47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 */
63	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
64	  sword: 1000,
65	  amulet: 600,
66	  staff: 800,
67	  potion: 400,
68	  rune: 250,
69	  moonstone: 250,
70	};
71	const DEDUCTIBLE = 100;
72	const CAP_MULTIPLE = 2;
73	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
74	const HIGH_ENCHANTMENT_PAYOUT_PERCENT = 50;
75	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
76	const CURSE_SURCHARGE_PERCENT = 50;
77	const HIGH_ENCHANTMENT_THRESHOLD = 5;
78	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
79	const LOYALTY_THRESHOLD_YEARS = 2;
80	const LOYALTY_DISCOUNT_PERCENT = 20;
81	const FOLLOWUP_DISCOUNT_PERCENT = 15;
82	const PROCESSING_FEE = 5;
83	
84	const percentOf = (amount: number, percent: number): number =>
85	  (amount * percent) / 100;
86	
87	/**
88	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
89	 * the opposite direction, so this deliberately names the premium case only
90	 * rather than a general "in the MHPCO's favour" rounding.
91	 */
92	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
93	
94	const BLOCK_SIZE = 3;
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
98	const countAlikeItems = (items: Item[]): Map<string, number> =>
99	  items.reduce(
100	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
101	    new Map<string, number>(),
102	  );
103	
104	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
105	
106	const basePremiumForAlikeItems = (type: string, count: number): number =>
107	  formsBuildingBlock(count)
108	    ? BLOCK_BASE_PREMIUM
109	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
110	
111	const policyBasePremium = (items: Item[]): number =>
112	  [...countAlikeItems(items)].reduce(
113	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
114	    0,
115	  );
116	
117	const itemBasePremium = (item: Item): number =>
118	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
119	
120	/**
121	 * An absent `enchantment` reads as 0 — a plain rune is not enchanted at all.
122	 * The threshold is a parameter because the MHPCO sets two different bars: 5
123	 * for the premium surcharge, 8 for the payout clause.
124	 */
125	const enchantmentAtLeast = (
126	  item: Item | undefined,
127	  threshold: number,
128	): boolean => (item?.enchantment ?? 0) >= threshold;
129	
130	const isHighlyEnchanted = (item: Item): boolean =>
131	  enchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD);
132	
133	/** Item-specific surcharges stack additively. */
134	const itemSurchargePercent = (item: Item): number =>
135	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
136	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
137	
138	/**
139	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
140	 * premium — unlike policy-wide modifiers, which apply to the policy base.
141	 */
142	const totalItemSurcharges = (items: Item[]): number =>
143	  items.reduce(
144	    (total, item) =>
145	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
146	    0,
147	  );
148	
149	const isLongStanding = (customer: Customer): boolean =>
150	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
151	
152	/**
153	 * The net of all policy-wide percentages. Policy-wide modifiers are
154	 * percentages of the POLICY base premium — unlike item-specific modifiers,
155	 * which apply to the affected item's own base. The net is negative when the
156	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
157	 */
158	const netPolicyAdjustmentPercent = (
159	  customer: Customer,
160	  precedingSteps: number,
161	): number =>
162	  FIRST_INSURANCE_SURCHARGE_PERCENT -
163	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
164	  // The follow-up discount is owed on every quote after the customer's FIRST
165	  // QUOTE, but what we have here is a count of preceding STEPS. The two
166	  // coincide only because every step exercised so far is a quote; once claim
167	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
168	  // as a second follow-up. No test forces the distinction yet.
169	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
170	
171	const policyAdjustment = (
172	  policyBase: number,
173	  customer: Customer,
174	  precedingSteps: number,
175	): number =>
176	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
177	
178	const quotePremium = (
179	  items: Item[],
180	  customer: Customer,
181	  precedingSteps: number,
182	): number => {
183	  const basePremium = policyBasePremium(items);
184	  return roundPremiumUp(
185	    basePremium +
186	      totalItemSurcharges(items) +
187	      policyAdjustment(basePremium, customer, precedingSteps) +
188	      PROCESSING_FEE,
189	  );
190	};
191	
192	const roundPayoutDown = (payout: number): number => Math.floor(payout);
193	
194	const insuranceSum = (items: Item[]): number =>
195	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);
196	
197	const damagedItem = (damage: Damage, policyItems: Item[]): Item | undefined =>
198	  policyItems.find((item) => item.type === damage.itemType);
199	
200	/**
201	 * What the MHPCO reimburses for ONE damaged item, before the deductible.
202	 * Highly enchanted items are reimbursed at half the damage amount.
203	 *
204	 * NOT A BUG: the spec's "dragon material is fully reimbursed" clause is
205	 * deliberately absent, because no example can observe it. Full reimbursement is
206	 * already what happens when no clause fires, so below enchantment 8 a dragon
207	 * item is indistinguishable from a steel one; at enchantment >= 8 the spec says
208	 * the 50 % rule wins, so dragon is indistinguishable again. The clause has no
209	 * input that would change an output — adding it would be unfalsifiable by the
210	 * suite. Both dragon tests below pass against this code for exactly the reasons
211	 * their comments state. If a future rule ever makes material observable (say, a
212	 * dragon-only exemption from the deductible, or a clause the 50 % rule does not
213	 * override), add it then, driven by that example.
214	 *
215	 * The enchantment is read from the FIRST policy item of the damaged type; see
216	 * `damagedItem`. With two alike items that differ in enchantment the wrong one
217	 * would be consulted — no example distinguishes them yet.
218	 */
219	const reimbursementFor = (damage: Damage, policyItems: Item[]): number =>
220	  enchantmentAtLeast(
221	    damagedItem(damage, policyItems),
222	    HIGH_ENCHANTMENT_PAYOUT_THRESHOLD,
223	  )
224	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_PAYOUT_PERCENT)
225	    : damage.amount;
226	
227	/**
228	 * The whole incident's payout, before rounding. Note the deductible is already
229	 * subtracted here — it comes off once per damaged item, not once per incident,
230	 * so it belongs inside this sum rather than after it. That is also why this is
231	 * NOT named for reimbursement: `reimbursementFor` above is the amount BEFORE
232	 * the deductible, and reusing that word here would invite a reader to subtract
233	 * it a second time.
234	 */
235	const payoutBeforeRounding = (incident: Incident, policyItems: Item[]): number =>
236	  incident.damages.reduce(
237	    (total, damage) =>
238	      total + reimbursementFor(damage, policyItems) - DEDUCTIBLE,
239	    0,
240	  );
241	
242	/** A claim's `policy` field is the index of the quote step that wrote it. */
243	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
244	  scenario.steps[policy].items ?? [];
245	
246	/** The MHPCO caps a policy at twice its insurance sum. */
247	const capFor = (policyItems: Item[]): number =>
248	  CAP_MULTIPLE * insuranceSum(policyItems);
249	
250	const claimResult = (step: Step, scenario: Scenario): ClaimResult => {
251	  const policyItems = itemsCoveredBy(step.policy ?? 0, scenario);
252	  const cap = capFor(policyItems);
253	  // Non-null: runScenario only routes here when op === "claim", and every
254	  // claim step carries an incident. See the Step doc comment.
255	  const payout = roundPayoutDown(
256	    payoutBeforeRounding(step.incident!, policyItems),
257	  );
258	  return { payout, remainingCap: cap - payout };
259	};
260	
261	export const runScenario = (scenario: Scenario): ScenarioResult => ({
262	  results: scenario.steps.map((step, precedingSteps) =>
263	    step.op === "claim"
264	      ? claimResult(step, scenario)
265	      : {
266	          premium: quotePremium(
267	            step.items ?? [],
268	            scenario.customer,
269	            precedingSteps,
270	          ),
271	        },
272	  ),
273	});
